    const fdot = (i) => 'display:block; height:8px; border-radius:999px; transition:width 0.3s ease, background 0.3s ease; ' + (i === this.state.fl ? 'width:24px; background:' + accent + ';' : 'width:8px; background:rgba(255,255,255,0.25);');
